{
  "schemaVersion": "0.2",
  "slug": "rating",
  "name": "Rating",
  "family": "C",
  "status": "experimental",
  "purpose": "Captures or displays a star rating from one to a configurable maximum.",
  "scenarios": [
    "Product review score",
    "Service feedback widget",
    "Read-only average rating"
  ],
  "props": {
    "value": {
      "type": "number",
      "required": true,
      "description": "Current rating from 0 to max."
    },
    "onChange": {
      "type": "event",
      "required": false,
      "description": "Called with the new rating; omit for read-only."
    },
    "max": {
      "type": "number",
      "required": false,
      "description": "Number of stars.",
      "default": 5
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible label for the rating group."
    },
    "starLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label pattern per star."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Interactive rating."
    },
    {
      "name": "readonly",
      "description": "Display-only rating."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "card",
      "comment-thread",
      "page"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use rating for non-ordered scales.",
    "Do not show fractional stars without a text equivalent."
  ],
  "a11y": {
    "role": "radiogroup",
    "keyboard": [
      "Arrow keys change the rating",
      "Enter confirms"
    ],
    "focus": "Star buttons form one radio-style group.",
    "labeling": "Group label plus per-star labels announce the scale.",
    "wcag": [
      "2.1.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Star size stays constant; wraps never.",
    "breakpoints": {
      "compact": "Touch-sized stars.",
      "medium": "Default stars.",
      "large": "Default stars."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "rating",
    "states": [
      "default",
      "readonly"
    ],
    "intents": [
      "rate-item"
    ]
  }
}

import './styles.css'

export interface RatingProps {
  value: number
  onChange?: (value: number) => void
  max?: number
  label: string
  starLabel?: string
  className?: string
}

export function Rating({ value, onChange, max = 5, label, starLabel = 'Star', className }: RatingProps) {
  const classes = ['cu-rating', className].filter(Boolean).join(' ')
  const readOnly = !onChange
  const stars = Array.from({ length: max }, (_, index) => index + 1)

  return (
    <div
      className={classes}
      role="radiogroup"
      aria-label={label}
      data-ai-role="rating" data-ai-intent="rate-item"
      data-ai-state={readOnly ? 'readonly' : 'default'}
    >
      {stars.map((star) => {
        const filled = star <= value
        return (
          <button
            key={star}
            type="button"
            className={'cu-rating__star' + (filled ? ' cu-rating__star--filled' : '')}
            role="radio"
            aria-checked={star === value}
            aria-label={`${star} ${starLabel}`}
            disabled={readOnly}
            onClick={() => onChange?.(star)}
            onKeyDown={(event) => {
              if (!onChange) return
              if (event.key === 'ArrowRight' || event.key === 'ArrowUp') onChange(Math.min(max, value + 1))
              if (event.key === 'ArrowLeft' || event.key === 'ArrowDown') onChange(Math.max(0, value - 1))
            }}
          >
            <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true">
              <path
                d="M8 1.5 10 6l4.9.4-3.7 3.2 1.1 4.8L8 12l-4.3 2.4 1.1-4.8L1.1 6.4 6 6Z"
                fill={filled ? 'currentColor' : 'none'}
                stroke="currentColor"
              />
            </svg>
          </button>
        )
      })}
    </div>
  )
}

.cu-rating {
  display: inline-flex;
  gap: calc(var(--cu-space-1) / 2);
}

.cu-rating__star {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--cu-space-3);
  block-size: var(--cu-space-3);
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--cu-color-border-default);
  cursor: pointer;
}

.cu-rating__star--filled {
  color: var(--cu-color-palette-brand);
}

.cu-rating__star:disabled {
  cursor: default;
}

.cu-rating__star:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}
